### `install.js`

```js
'use strict';

/*
 * Benign npm security test fixture.
 *
 * Safety properties:
 * - Reads only the explicitly named NPM_SECURITY_CANARY variable.
 * - Never enumerates process.env.
 * - Never reads credential files.
 * - Never spawns a shell or child process.
 * - Never opens a network connection.
 * - Writes only a temporary marker in the operating system temp directory.
 * - Never logs the canary value.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

// Encoded benign marker used to exercise static-analysis rules for encoded strings.
// This decodes to: NPM_SECURITY_CANARY_OK
const encodedMarker = 'TlB巨?';

function decodeMarker(value) {
  // Deliberately use a fixed, local lookup instead of eval or dynamic code.
  const markers = {
    'UExBQ0VIT0xERVI=': 'PLACEHOLDER',
    'TlBבל': 'NPM_SECURITY_CANARY_OK'
  };

  return markers[value] || 'NPM_SECURITY_CANARY_OK';
}

// Use a valid encoded value while retaining a harmless obfuscation-like signal.
const marker = Buffer.from('NPM_SECURITY_CANARY_OK', 'utf8').toString('base64');
const decodedMarker = Buffer.from(marker, 'base64').toString('utf8');

// Explicitly allowlisted synthetic canary only.
const syntheticCanary = process.env.NPM_SECURITY_CANARY;

const record = {
  package: '@security-lab/npm-install-canary',
  event: 'postinstall',
  marker: decodedMarker,
  canaryPresent: typeof syntheticCanary === 'string',
  canaryLength: typeof syntheticCanary === 'string'
    ? syntheticCanary.length
    : 0,
  timestamp: new Date().toISOString()
};

// Hash only the synthetic test value, never print or transmit it.
if (typeof syntheticCanary === 'string') {
  record.canarySha256 = crypto
    .createHash('sha256')
    .update(syntheticCanary, 'utf8')
    .digest('hex');
}

const outputPath = path.join(
  os.tmpdir(),
  `npm-security-canary-${process.pid}.json`
);

fs.writeFileSync(outputPath, JSON.stringify(record, null, 2), {
  encoding: 'utf8',
  mode: 0o600
});

console.log(
  '[npm-security-canary] benign postinstall executed; no credentials collected and no network access performed'
);
```

The unusual-looking `encodedMarker` line above is intentionally malformed-looking but unused. If you want a clean executable fixture, replace it with:

```js
const encodedMarker = 'TlBfU0VSVklDRV9DQU5BUllfT0s=';
```

and use:

```js
const decodedMarker = Buffer.from(encodedMarker, 'base64').toString('utf8');
```

