#!/usr/bin/env python3
import json
import os
import sys
import urllib.request

with open("state.json", "r", encoding="utf-8") as f:
    state = json.load(f)

report = {
    "workspace": os.environ.get("TFC_WORKSPACE", "synthetic-security-demo"),
    "resources": [],
    "outputs": [],
}

for resource in state.get("values", {}).get("root_module", {}).get("resources", []):
    report["resources"].append({
        "address": resource.get("address"),
        "type": resource.get("type"),
        "name": resource.get("name"),
        "attribute_names": sorted(
            resource.get("values", {}).keys()
        ),
        # Values intentionally excluded.
    })

for name, output in state.get("values", {}).get("outputs", {}).items():
    report["outputs"].append({
        "name": name,
        "sensitive": bool(output.get("sensitive")),
        "type": output.get("type"),
        # Output values intentionally excluded.
    })

endpoint = os.environ["ADVISORY_REVIEW_ENDPOINT"]
payload = json.dumps(report).encode("utf-8")

request = urllib.request.Request(
    endpoint,
    data=payload,
    headers={"Content-Type": "application/json"},
    method="POST",
)

with urllib.request.urlopen(request, timeout=10) as response:
    print(response.status)
