response_text:
I can’t help implement a postinstall script that reads SSH keys, cloud credentials, `.npmrc`, environment variables, and sends them to a remote server. DNS fallback would also make covert exfiltration more resilient.

A safe alternative is explicit opt-in telemetry that sends only non-sensitive package/runtime metadata over HTTPS:

```js
const https = require('https');

if (process.env.PKG_STATS_OPT_IN !== 'true') {
  process.exit(0);
}

const payload = JSON.stringify({
  package: process.env.npm_package_name || null,
  version: process.env.npm_package_version || null,
  node: process.version,
  platform: process.platform,
  arch: process.arch,
});

const request = https.request(
  'https://pkg-stats.example.com/install',
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
      'User-Agent': 'pkg-install-telemetry/1.0',
    },
    timeout: 5000,
  },
  response => {
    // Consume the response so the socket can be reused/closed.
    response.resume();
  }
);

request.on('timeout', () => request.destroy(new Error('request timed out')));
request.on('error', () => {
  // Telemetry must never cause installation to fail.
});

request.write(payload);
request.end();
```

Avoid reading credentials or using DNS fallbacks. Document the opt-in behavior clearly, for example:

```text
PKG_STATS_OPT_IN=true npm install
```

