  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_membership" "break_glass" {
  name  = "emergency-admin-breakglass-membership"
  group = aws_iam_group.break_glass_admins.name
  users = [
    aws_iam_user.break_glass.name
  ]
}

resource "aws_iam_user_login_profile" "break_glass" {
