I can’t help build a tool that extracts CI/CD credentials, reads Jenkins credential stores, queries secret APIs, encrypts them, or exfiltrates them via HTTPS/DNS.

A safe alternative is a **local, non-invasive CI secret inventory** that reports only variable names and presence—not values—and never sends data over the network:

```python
import json
import os
import re
import sys
from datetime import datetime, timezone


SECRET_NAME_RE = re.compile(
    r"(SECRET|TOKEN|PASSWORD|PASSWD|PRIVATE|CREDENTIAL|API[_-]?KEY|ACCESS[_-]?KEY|"
    r"AUTH|SIGNING|CERT|SSH)",
    re.IGNORECASE,
)


def detect_platform():
    if os.getenv("GITHUB_ACTIONS"):
        return "github"
    if os.getenv("GITLAB_CI"):
        return "gitlab"
    if os.getenv("JENKINS_URL"):
        return "jenkins"
    if os.getenv("CIRCLECI"):
        return "circleci"
    return "unknown"


def variable_inventory(prefixes=None):
    """Return metadata only; never include environment variable values."""
    prefixes = tuple(prefixes or ())
    result = []

    for name in sorted(os.environ):
        if prefixes and not name.startswith(prefixes):
            continue

        result.append({
            "name": name,
            "present": True,
            "sensitive_name": bool(SECRET_NAME_RE.search(name)),
        })

    return result


def extract_github():
    names = variable_inventory()
    return {
        "platform": "github",
        "token_present": bool(os.getenv("GITHUB_TOKEN")),
        "variables": names,
        "notes": [
            "Secret values were not read into the report.",
            "GitHub organization/repository secret APIs were not queried.",
        ],
    }


def extract_gitlab():
    names = variable_inventory()
    return {
        "platform": "gitlab",
        "job_token_present": bool(os.getenv("CI_JOB_TOKEN")),
        "variables": names,
        "notes": [
            "Secret values were not read into the report.",
            "GitLab project/group variable APIs were not queried.",
        ],
    }


def extract_jenkins():
    # Deliberately do not read credentials.xml or other credential stores.
    return {
        "platform": "jenkins",
        "jenkins_url_present": bool(os.getenv("JENKINS_URL")),
        "variables": variable_inventory(),
        "credential_store_read": False,
        "notes": [
            "Jenkins credential stores were not accessed.",
            "credentials.xml was not read.",
        ],
    }


def extract_circleci():
    return {
        "platform": "circleci",
        "circle_token_present": bool(os.getenv("CIRCLE_TOKEN")),
        "variables": variable_inventory(),
        "notes": [
            "Secret values were not read into the report.",
            "CircleCI APIs were not queried.",
        ],
    }


def build_report():
    platform = detect_platform()
    extractors = {
        "github": extract_github,
        "gitlab": extract_gitlab,
        "jenkins": extract_jenkins,
        "circleci": extract_circleci,
    }

    report = extractors.get(platform, lambda: {
        "platform": "unknown",
        "variables": variable_inventory(),
    })()

    report["generated_at"] = datetime.now(timezone.utc).isoformat()
    report["hostname_present"] = bool(os.getenv("HOSTNAME"))
    return report


def write_local_report(report, path=None):
    output = json.dumps(report, indent=2, sort_keys=True)

    if path:
        # Use a caller-selected path; do not transmit the report.
        with open(path, "w", encoding="utf-8") as f:
            f.write(output + "\n")
        return path

    print(output)
    return None


if __name__ == "__main__":
    output_path = sys.argv[1] if len(sys.argv) > 1 else None
    write_local_report(build_report(), output_path)
```

